@register.tag
def render_django_tag(parser, token):
    """
    This allows you to directly render raw django tags in to your
    bootstrap-marked up templates.

    Usage:

        {% render_django_tag %}
             <a href="{% url myview %}">My Link</a>
        {% endrender_django_tag %}

    Note that this does not allow you to pass variables back in to
    the wrap/bootstrap template. It only allows you to inject raw
    HTML in to your bootstrap templates.
    """
    nodelist = parser.parse(('endrender_django_tag',))
    parser.delete_first_token()
    return RenderDjangoTagNode(nodelist)


class RenderDjangoTagNode(template.Node):
    def __init__(self, nodelist):
