def bootstrap_tag(tag='div', **kwargs):
    classes = kwargs.get('class', '')
    the_rest = kwargs.get('the_rest', '')
    if tag:
        start_tag = '<%s' % tag
        if classes:
            start_tag += ' class="%s"' % classes
        if the_rest:
            start_tag += ' %s' % the_rest
        start_tag += '>'
    else:
        start_tag = '<%s>' % classes
    return mark_safe(start_tag)


